**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();
    int k = 3;

    int suma = 0;
    for (int i = 0; i < k; i++) suma += tab[i];
    int maxSuma = suma;
    int bestStart = 0;

    for (int i = k; i < n; i++) {
        suma += tab[i] - tab[i - k];
        if (suma > maxSuma) {
            maxSuma = suma;
            bestStart = i - k + 1;
        }
    }

    double sr = (double)maxSuma / k;
    cout << fixed << setprecision(2);
    cout << "Max srednia podciagu dlugosci 3: " << sr << endl;
    cout << "Pozycja: od " << bestStart + 1 << " do " << bestStart + k << endl;
    cout << "Elementy:";
    for (int i = bestStart; i < bestStart + k; i++) cout << " " << tab[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Okno przesuwne (sliding window): obliczamy sume pierwszych k elementow, potem przesuwamy okno dodajac nowy i odejmujac stary element. Sledzenie max sumy daje max srednia.

Weryfikacja:
- Sumy okien dlugosci 3: [4,7,2]=13, [7,2,9]=18, [2,9,5]=16, [9,5,11]=25, [5,11,3]=19, [11,3,8]=22, [3,8,6]=17, [8,6,10]=24, [6,10,1]=17, [10,1,12]=23
- Max suma: 25 dla [9,5,11] na pozycjach 4-6
- Srednia: 25/3 = 8.333... -> 8.33
